276: function collectEvidence(def) {
277:   if (def.taken) return;
278:   def.taken = true;
279:   evidence++;
280:   if (def.prop) {
281:     def.prop.traverse(o => {
282:       if (o.isMesh && o.material && o.material.color) o.material = mat('evidence taken', 0x25271f, 0.95);
283:     });
284:   }
285:   openNote(def.title, def.body);
286:   toast(`EVIDENCE ${String(evidence).padStart(2, '0')} / 05 RECOVERED`);
287:   if (evidence < 5) {
288:     setObjective('Recover the remaining evidence', `${evidence} of 5 recordings secured. Search the rooms off the halls.`);
289:   } else {
290:     entityAlert = true;
291:     setObjective('IT IS AWAKE. RUN.', 'Get back to the entry gate. Do not stop.');
292:     facility.wake();
293:     flashEl.classList.remove('bang'); void flashEl.offsetWidth; flashEl.classList.add('bang');
294:     toast('SUBJECT 06 IS AWAKE');
295:   }
296: }
