602:   /* ---------------- path grid ---------------- */
603:   const PATH = { cell: 1, x0: F.minX + 0.5, z0: F.minZ + 0.5, w: 60, h: 54, walk: null };
604:   function buildPathGrid() {
605:     const w = PATH.w, h = PATH.h;
606:     PATH.walk = new Uint8Array(w * h);
607:     for (let iz = 0; iz < h; iz++) for (let ix = 0; ix < w; ix++) {
608:       const x = PATH.x0 + ix * PATH.cell, z = PATH.z0 + iz * PATH.cell;
609:       let ok = x > F.minX + 0.45 && x < F.maxX - 0.45 && z > F.minZ + 0.45 && z < F.maxZ - 0.45;
610:       if (ok) {
611:         for (let i = 0; i < solids.lab.length; i++) {
612:           const c = solids.lab[i];
613:           if (c.disabled) continue;
614:           if (Math.abs(x - c.x) < c.hx + 0.34 && Math.abs(z - c.z) < c.hz + 0.34) { ok = false; break; }
615:         }
616:       }
617:       PATH.walk[iz * w + ix] = ok ? 1 : 0;
618:     }
619:   }
620:   buildPathGrid();
621: 
622:   function walkableNear(ix, iz) {
623:     if (PATH.walk[iz * PATH.w + ix]) return [ix, iz];
624:     for (let r = 1; r <= 5; r++) for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
625:       if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
626:       const nx = ix + dx, nz = iz + dz;
627:       if (nx < 0 || nz < 0 || nx >= PATH.w || nz >= PATH.h) continue;
628:       if (PATH.walk[nz * PATH.w + nx]) return [nx, nz];
629:     }
630:     return null;
631:   }
632: 
633:   function findPath(sx, sz, tx, tz) {
634:     if (!PATH.walk) return null;
635:     const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
636:     const six = clamp(Math.round(sx - PATH.x0), 0, PATH.w - 1);
637:     const siz = clamp(Math.round(sz - PATH.z0), 0, PATH.h - 1);
638:     const tix = clamp(Math.round(tx - PATH.x0), 0, PATH.w - 1);
639:     const tiz = clamp(Math.round(tz - PATH.z0), 0, PATH.h - 1);
640:     const start = walkableNear(six, siz), goal = walkableNear(tix, tiz);
641:     if (!start || !goal) return null;
642:     const w = PATH.w, h = PATH.h;
643:     const s = start[1] * w + start[0], t = goal[1] * w + goal[0];
644:     const prev = new Int32Array(w * h).fill(-1);
645:     const seen = new Uint8Array(w * h);
646:     const q = new Int32Array(w * h);
647:     let head = 0, tail = 0;
648:     q[tail++] = s; seen[s] = 1;
649:     while (head < tail && !seen[t]) {
650:       const cur = q[head++];
651:       const cx = cur % w, cz = (cur / w) | 0;
652:       for (let k = 0; k < 4; k++) {
653:         const nx = cx + (k === 0 ? 1 : k === 1 ? -1 : 0);
654:         const nz = cz + (k === 2 ? 1 : k === 3 ? -1 : 0);
655:         if (nx < 0 || nz < 0 || nx >= w || nz >= h) continue;
656:         const ni = nz * w + nx;
657:         if (seen[ni] || !PATH.walk[ni]) continue;
658:         seen[ni] = 1; prev[ni] = cur; q[tail++] = ni;
659:       }
660:     }
661:     if (!seen[t]) return null;
662:     const path = [];
663:     let cur = t;
664:     while (cur !== s) {
665:       path.push({ x: PATH.x0 + (cur % w), z: PATH.z0 + ((cur / w) | 0) });
666:       cur = prev[cur];
667:       if (cur < 0) return null;
668:     }
669:     path.reverse();
670:     return path;
671:   }
